  if (r === null) { s.proc.kill('SIGKILL'); await s.done; return { code: 'TIMEOUT', out: s.out, err: s.err }; }
  return { code: r.code, out: s.out, err: s.err };
}

async function startServer(env = {}, cwd = newDir('cwd')) {
